insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-peh-note-101','Pharmacy','Diploma in Pharmacy','note','free',1301,'{"title":"Introduction to Pharmacoepidemiology","english":"Pharmacoepidemiology is the study of the use and effects of medicines in large populations. It applies epidemiological methods to understand medicine utilization, benefits, risks and patterns of use in real-world settings. It can help identify uncommon or delayed adverse effects, compare treatment outcomes, assess medicine-use patterns and support evidence-informed health policy. Findings should be interpreted carefully because observational studies may be affected by confounding, bias and incomplete data.","nepali":"Pharmacoepidemiology भनेको ठूलो जनसमुदायमा औषधिको प्रयोग र प्रभावको अध्ययन हो। यसले वास्तविक जीवनमा औषधिको उपयोग, लाभ, जोखिम र प्रयोगको ढाँचा बुझ्न epidemiology का विधि प्रयोग गर्छ। यसबाट दुर्लभ वा ढिलो देखिने adverse effect पहिचान, उपचारको नतिजा तुलना, औषधि प्रयोगको ढाँचा मूल्याङ्कन र प्रमाणमा आधारित स्वास्थ्य नीति बनाउन सहयोग हुन्छ। Observational study मा confounding, bias र अपूर्ण data हुन सक्ने भएकाले नतिजा सावधानीपूर्वक बुझ्नुपर्छ।"}'::jsonb,true),
('dph-peh-note-102','Pharmacy','Diploma in Pharmacy','note','free',1302,'{"title":"Basic Epidemiological Measures and Study Designs","english":"Incidence measures new cases occurring in a population during a specified period, while prevalence measures all existing cases at a given time or over a stated period. A cohort study follows groups over time to compare outcomes; a case-control study starts with people who have an outcome and compares prior exposures; a cross-sectional study measures exposure and outcome at one point or short period. Randomized controlled trials allocate interventions by chance and can provide strong evidence of efficacy when properly designed. Choose a study design according to the research question.","nepali":"Incidence ले निश्चित अवधिमा जनसमुदायमा देखिएका नयाँ घटनाको मापन गर्छ भने prevalence ले निश्चित समय वा अवधिमा रहेका सबै घटनाको मापन गर्छ। Cohort study ले समूहलाई समयसँगै follow गरेर नतिजा तुलना गर्छ; case-control study ले outcome भएका र नभएका व्यक्तिबीच पहिलेको exposure तुलना गर्छ; cross-sectional study ले एउटै समय वा छोटो अवधिमा exposure र outcome मापन गर्छ। Randomized controlled trial मा intervention संयोगका आधारमा बाँडिन्छ र राम्रो डिजाइन भए प्रभावकारिताको बलियो प्रमाण दिन सक्छ। अनुसन्धान प्रश्नअनुसार study design छान्नुपर्छ।"}'::jsonb,true),
('dph-peh-note-103','Pharmacy','Diploma in Pharmacy','note','free',1303,'{"title":"Medicine Utilization Review and Drug Use Evaluation","english":"Medicine utilization review studies how medicines are prescribed, dispensed and used. Drug use evaluation (DUE) assesses medicine use against predefined criteria to improve appropriateness, safety and outcomes. It may examine indication, medicine selection, dose, route, duration, monitoring and patient response. The process includes selecting a medicine or problem, setting standards, collecting data, comparing practice with standards, providing feedback and reassessing after changes. The aim is improvement, not blame.","nepali":"Medicine utilization review ले औषधि कसरी prescribe, dispense र प्रयोग गरिन्छ भन्ने अध्ययन गर्छ। Drug use evaluation (DUE) ले औषधिको प्रयोगलाई पहिल्यै तोकिएका मापदण्डसँग तुलना गरी उचितता, सुरक्षा र नतिजा सुधार गर्छ। यसमा indication, औषधि छनोट, dose, route, अवधि, monitoring र बिरामीको response जाँच्न सकिन्छ। प्रक्रिया अन्तर्गत औषधि वा समस्या छनोट, standard निर्धारण, data संकलन, अभ्याससँग तुलना, feedback र परिवर्तनपछि पुनः मूल्याङ्कन पर्छन्। यसको उद्देश्य दोष लगाउनु होइन, सुधार गर्नु हो।"}'::jsonb,true),
('dph-peh-note-104','Pharmacy','Diploma in Pharmacy','note','free',1304,'{"title":"Environmental Health, Water, Sanitation and Waste","english":"Environmental health considers environmental factors that affect human health, including safe water, sanitation, hygiene, air quality, housing, food safety and waste management. Poor sanitation and contaminated water can spread infectious diseases. Healthcare facilities should segregate waste at the point of generation, use appropriate labeled containers, handle sharps in puncture-resistant containers and follow current national and institutional healthcare-waste procedures. Never mix infectious or sharps waste with ordinary general waste.","nepali":"Environmental health ले सुरक्षित पानी, सरसफाइ, स्वच्छता, हावाको गुणस्तर, आवास, खाद्य सुरक्षा र फोहोर व्यवस्थापनजस्ता मानव स्वास्थ्यमा असर गर्ने वातावरणीय पक्ष अध्ययन गर्छ। कमजोर सरसफाइ र दूषित पानीले संक्रामक रोग फैलाउन सक्छ। स्वास्थ्य संस्थाले फोहोर उत्पादन भएको स्थानमै छुट्याउने, उचित label भएका container प्रयोग गर्ने, धारिला वस्तु puncture-resistant container मा राख्ने र हालको राष्ट्रिय तथा संस्थागत healthcare-waste प्रक्रिया पालना गर्नुपर्छ। संक्रामक वा धारिलो फोहोरलाई सामान्य फोहोरसँग मिसाउनु हुँदैन।"}'::jsonb,true),
('dph-peh-note-105','Pharmacy','Diploma in Pharmacy','note','free',1305,'{"title":"Public Health Prevention, Surveillance and Health Education","english":"Public health prevention includes primary prevention to reduce the occurrence of disease, secondary prevention to detect disease early and tertiary prevention to reduce complications and disability. Disease surveillance is the systematic collection, analysis, interpretation and sharing of health data for public-health action. Pharmacy professionals can support public health through accurate medicine information, vaccination programmes where trained and authorized, adherence counselling, antimicrobial stewardship, health education and timely referral. Protect confidentiality and follow approved reporting channels.","nepali":"Public health prevention मा रोग हुन नदिन primary prevention, रोग चाँडै पत्ता लगाउन secondary prevention र जटिलता तथा अशक्तता घटाउन tertiary prevention पर्छन्। Disease surveillance भनेको जनस्वास्थ्य कार्यका लागि स्वास्थ्य तथ्यांक व्यवस्थित रूपमा संकलन, विश्लेषण, व्याख्या र साझा गर्ने प्रक्रिया हो। Pharmacy professional ले सही औषधि जानकारी, तालिम र अनुमति भएको अवस्थामा vaccination कार्यक्रम, औषधि नियमित प्रयोग परामर्श, antimicrobial stewardship, स्वास्थ्य शिक्षा र समयमै referral मार्फत सहयोग गर्न सक्छन्। गोपनीयता कायम राखी स्वीकृत reporting channel पालना गर्नुपर्छ।"}'::jsonb,true),
('dph-peh-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',1301,'{"question":"Pharmacoepidemiology is the study of:","translation":"Pharmacoepidemiology ले के अध्ययन गर्छ?","options":["Use and effects of medicines in populations","Only drug packaging design","Only plant classification","Hospital architecture"],"correctIndex":0,"explanation":"It studies medicine use and effects in large populations using epidemiological methods.","explanationNe":"यसले epidemiology का विधिबाट जनसमुदायमा औषधिको प्रयोग र प्रभाव अध्ययन गर्छ।"}'::jsonb,true),
('dph-peh-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',1302,'{"question":"Incidence refers to:","translation":"Incidence भन्नाले के बुझिन्छ?","options":["New cases during a specified period","All existing cases at a given time","Number of hospital beds","Total medicine sales"],"correctIndex":0,"explanation":"Incidence measures new cases arising in a population during a defined period.","explanationNe":"Incidence ले निश्चित अवधिमा जनसमुदायमा देखिएका नयाँ घटनाको मापन गर्छ।"}'::jsonb,true),
('dph-peh-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',1303,'{"question":"Prevalence measures:","translation":"Prevalence ले के मापन गर्छ?","options":["All existing cases at a specified time or period","Only new cases","Only deaths due to medicine","Only treatment cost"],"correctIndex":0,"explanation":"Prevalence includes all existing cases at a specified time or over a stated period.","explanationNe":"Prevalence ले निश्चित समयमा वा अवधिमा रहेका सबै घटनाको मापन गर्छ।"}'::jsonb,true),
('dph-peh-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',1304,'{"question":"Which study design follows exposed and unexposed groups over time?","translation":"Exposure भएका र नभएका समूहलाई समयसँगै follow गर्ने अध्ययन कुन हो?","options":["Cohort study","Case report","Cross-sectional study only","Laboratory calibration"],"correctIndex":0,"explanation":"A cohort study follows groups over time to compare the occurrence of outcomes.","explanationNe":"Cohort study ले समूहलाई समयसँगै follow गरेर outcome को घटना तुलना गर्छ।"}'::jsonb,true),
('dph-peh-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',1305,'{"question":"A case-control study usually begins by selecting participants according to:","translation":"Case-control study मा सहभागी सामान्यतया कुन आधारमा छनोट गरिन्छ?","options":["Whether they have the outcome or disease","Their height only","The brand of their phone","Their preferred pharmacy"],"correctIndex":0,"explanation":"Case-control studies select cases and controls based on outcome status, then compare prior exposures.","explanationNe":"Case-control study मा रोग वा outcome भएको र नभएको आधारमा समूह छानी पहिलेको exposure तुलना गरिन्छ।"}'::jsonb,true),
('dph-peh-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',1306,'{"question":"Drug use evaluation aims to:","translation":"Drug use evaluation को उद्देश्य के हो?","options":["Improve appropriate and safe medicine use","Increase irrational prescribing","Remove all medicine records","Promote unnecessary treatment"],"correctIndex":0,"explanation":"DUE compares practice with standards to improve medicine-use quality and safety.","explanationNe":"DUE ले औषधि प्रयोगलाई मापदण्डसँग तुलना गरी गुणस्तर र सुरक्षा सुधार गर्छ।"}'::jsonb,true),
('dph-peh-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',1307,'{"question":"Which is an example of primary prevention?","translation":"Primary prevention को उदाहरण कुन हो?","options":["Immunization to prevent disease","Rehabilitation after disability","Screening to detect early disease","Treating established complications"],"correctIndex":0,"explanation":"Primary prevention aims to prevent disease before it occurs; immunization is a common example.","explanationNe":"Primary prevention ले रोग हुनुअघि रोकथाम गर्छ; खोप यसको सामान्य उदाहरण हो।"}'::jsonb,true),
('dph-peh-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',1308,'{"question":"Healthcare waste segregation should take place:","translation":"स्वास्थ्य संस्थाको फोहोर छुट्याउने काम कहाँ गर्नुपर्छ?","options":["At the point where waste is generated","After mixing all waste together","Only outside the facility","Only at the final disposal site"],"correctIndex":0,"explanation":"Segregation at source reduces exposure and makes safe waste handling easier.","explanationNe":"फोहोर उत्पादन भएको स्थानमै छुट्याउँदा जोखिम घट्छ र सुरक्षित व्यवस्थापन सजिलो हुन्छ।"}'::jsonb,true),
('dph-peh-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',1309,'{"question":"Sharps waste should be placed in:","translation":"धारिला स्वास्थ्यजन्य फोहोर कहाँ राख्नुपर्छ?","options":["Puncture-resistant sharps container","Open paper bag","Ordinary food bin","Unlabeled water bottle"],"correctIndex":0,"explanation":"Puncture-resistant containers reduce needle-stick and sharps injuries.","explanationNe":"Puncture-resistant container ले सुई वा धारिलो वस्तुबाट हुने चोटको जोखिम घटाउँछ।"}'::jsonb,true),
('dph-peh-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',1310,'{"question":"Disease surveillance involves:","translation":"Disease surveillance मा के समावेश हुन्छ?","options":["Systematic collection and analysis of health data","Only advertising medicines","Only counting pharmacy shelves","Avoiding reports"],"correctIndex":0,"explanation":"Surveillance systematically collects, analyzes, interprets and shares health data for action.","explanationNe":"Surveillance ले कार्यका लागि स्वास्थ्य तथ्यांक व्यवस्थित रूपमा संकलन, विश्लेषण, व्याख्या र साझा गर्छ।"}'::jsonb,true),
('dph-peh-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',1301,'{"question":"Define pharmacoepidemiology and state three reasons it is important.","answer":"Pharmacoepidemiology studies the use and effects of medicines in populations. It helps understand real-world medicine use, identify potential safety signals and adverse effects, compare outcomes and inform medicine policy.","answerNe":"Pharmacoepidemiology ले जनसमुदायमा औषधिको प्रयोग र प्रभाव अध्ययन गर्छ। यसले वास्तविक औषधि प्रयोग बुझ्न, सम्भावित सुरक्षा संकेत तथा adverse effect पहिचान गर्न, नतिजा तुलना गर्न र औषधि नीतिमा सहयोग गर्छ।"}'::jsonb,true),
('dph-peh-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',1302,'{"question":"Differentiate incidence and prevalence.","answer":"Incidence measures new cases occurring in a population during a specified period. Prevalence measures all existing cases at a specified time or over a stated period.","answerNe":"Incidence ले निश्चित अवधिमा देखिएका नयाँ घटना मापन गर्छ। Prevalence ले निश्चित समयमा वा अवधिमा रहेका सबै घटना मापन गर्छ।"}'::jsonb,true),
('dph-peh-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',1303,'{"question":"Briefly compare cohort, case-control and cross-sectional studies.","answer":"A cohort study follows groups over time to compare outcomes. A case-control study selects participants by outcome status and compares previous exposures. A cross-sectional study measures exposure and outcome at one point or short period.","answerNe":"Cohort study ले समूहलाई समयसँगै follow गरी outcome तुलना गर्छ। Case-control study ले outcome का आधारमा समूह छानी पहिलेको exposure तुलना गर्छ। Cross-sectional study ले एउटै समय वा छोटो अवधिमा exposure र outcome मापन गर्छ।"}'::jsonb,true),
('dph-peh-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',1304,'{"question":"What is drug use evaluation? Outline its basic steps.","answer":"Drug use evaluation assesses medicine use against predefined standards. Basic steps include selecting a medicine or issue, defining criteria, collecting data, comparing findings with standards, giving feedback, implementing improvements and reassessing.","answerNe":"Drug use evaluation ले औषधि प्रयोगलाई पहिल्यै तोकिएका मापदण्डसँग तुलना गर्छ। मुख्य चरणमा औषधि वा समस्या छनोट, criteria निर्धारण, data संकलन, मापदण्डसँग तुलना, feedback, सुधार लागू र पुनः मूल्याङ्कन पर्छन्।"}'::jsonb,true),
('dph-peh-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',1305,'{"question":"Explain safe healthcare-waste segregation and give three examples of good practice.","answer":"Segregate waste at the point of generation using the current approved color-coded or labeled containers. Keep sharps in puncture-resistant containers, do not mix infectious waste with general waste and follow facility and national waste-management procedures.","answerNe":"हाल स्वीकृत रंग वा label भएका container प्रयोग गरी फोहोर उत्पादन भएको स्थानमै छुट्याउनुपर्छ। धारिला वस्तु puncture-resistant container मा राख्ने, संक्रामक फोहोर सामान्य फोहोरमा नमिसाउने र संस्थागत तथा राष्ट्रिय फोहोर व्यवस्थापन प्रक्रिया पालना गर्ने।"}'::jsonb,true)
